import { loadFont } from "@remotion/google-fonts/Montserrat";
import React from "react";
import { AbsoluteFill, Easing, Img, interpolate, staticFile, useCurrentFrame } from "remotion";

// INOVA MÍDIAS (Londrina). Motion vertical do "Raio-X do seu Instagram": análise personalizada em PDF, até 24 h, R$ 98.
// Roteiro v1 condensado do texto do cliente ((arquivo do cliente)). Os tempos em C são os da locução
// (t = 0 é o começo do mp3; o vídeo tem LEAD de entrada). Tempos medidos na voz v1 (public/inova/voz-v1.mp3, 28,2 s); preco é o "por apenas", o número entra no "noventa" (23,85).
// Identidade da arte do post e do logo: azul-preto #0A0F15, laranja #F58A3C, branco, sem serifa pesada, rótulos espaçados.
// Tom profissional e direto: entradas firmes, nada de confete. No trecho do problema o visual é genérico; a marca
// estreia junto com a solução. Limpo: fundo liso, o texto entra e fica parado; o movimento contínuo fica nos objetos.

const { fontFamily: FONT } = loadFont("normal", { weights: ["500", "600", "700", "800", "900"], subsets: ["latin", "latin-ext"] });

export const INOVA_FPS = 30;
const LEAD = 0.3;

// tempos da fala
const C = {
  porque: 0.75, insta: 1.31, nao: 1.91, seg: 2.95, cli: 3.6,
  talvez: 4.97, quant: 6.63,
  conheca: 8.35, raiox: 8.99, analise: 10.71, cem: 11.71, receita: 13.63,
  descobre: 15.21, nota: 15.91, trava: 17.3, mudar: 19.34,
  pdf: 20.68, horas: 21.84, preco: 23.4,
  chama: 25.54, solicite: 26.6, fim: 27.85,
};
// trocas de cena
const T2 = C.talvez - 0.15, T3 = C.conheca - 0.15, T4 = C.descobre - 0.2, T5 = C.pdf - 0.2, T6 = C.chama - 0.2;
const END = C.fim + 0.25;                       // cartão final
export const INOVA_FRAMES = Math.round((END + 2.2 + LEAD) * INOVA_FPS);

const cl = { extrapolateLeft: "clamp", extrapolateRight: "clamp" } as const;
const OUT = Easing.bezier(0.16, 1, 0.3, 1);
const BACK = Easing.out(Easing.back(1.7));
const INOUT = Easing.bezier(0.65, 0, 0.35, 1);
const k = (t: number, a: number, d = 0.45) => interpolate(t, [a, a + d], [0, 1], { ...cl, easing: OUT });
const pop = (t: number, a: number, d = 0.4) => interpolate(t, [a, a + d], [0, 1], { ...cl, easing: BACK });
const lin = (t: number, a: number, b: number) => interpolate(t, [a, b], [0, 1], cl);
const io = (t: number, a: number, b: number) => interpolate(t, [a, b], [0, 1], { ...cl, easing: INOUT });
const bump = (t: number, a: number, d = 0.4) => (t < a || t > a + d ? 0 : Math.sin(((t - a) / d) * Math.PI) * (1 - (t - a) / d));
const shake = (t: number, a: number, d = 0.5, amp = 14) => (t < a || t > a + d ? 0 : Math.sin((t - a) * 46) * amp * (1 - (t - a) / d));

const BG = "#0A0F15";
const CARD = "#141A23";
const EDGE = "#262E3B";
const ORANGE = "#F58A3C";
const WHITE = "#FFFFFF";
const DIM = "rgba(255,255,255,0.56)";
const PAPER = "#F3EFE9";
const INK = "#0A0F15";
const COL = 840;                                // coluna central (margem de 120)

// texto: entra com opacidade e escala, sem deslocar, e fica parado; sai apagando no mesmo lugar
const tin = (t: number, at: number, out?: number, d = 0.36): React.CSSProperties => {
  const e = pop(t, at, d);
  const o = out === undefined ? 0 : lin(t, out, out + 0.16);
  return { opacity: Math.min(1, lin(t, at, at + 0.12) * 1.2) * (1 - o), transform: `scale(${(0.8 + 0.2 * e).toFixed(4)})` };
};
type L = [React.ReactNode, number, number?, string?];  // texto, entrada, tamanho, cor
const Title: React.FC<{ t: number; items: L[]; size: number; top: number; color?: string; out?: number }> = ({ t, items, size, top, color = WHITE, out }) => (
  <div style={{ position: "absolute", left: 0, right: 0, top, display: "flex", flexDirection: "column", alignItems: "center", gap: size * 0.1 }}>
    {items.map(([w, at, sz, c], i) => (
      <div key={i} style={{ fontFamily: FONT, fontWeight: 800, fontSize: sz ?? size, lineHeight: 1.08, letterSpacing: "-0.025em", whiteSpace: "nowrap", color: c ?? color, ...tin(t, at, out) }}>{w}</div>
    ))}
  </div>
);
const Caps: React.FC<{ children: React.ReactNode; size?: number; color?: string; style?: React.CSSProperties }> = ({ children, size = 28, color = DIM, style }) => (
  <div style={{ fontFamily: FONT, fontWeight: 600, fontSize: size, letterSpacing: "0.22em", textTransform: "uppercase", color, whiteSpace: "nowrap", ...style }}>{children}</div>
);
const O: React.FC<{ children: React.ReactNode }> = ({ children }) => <span style={{ color: ORANGE }}>{children}</span>;
// brilho leve da cor da marca atrás do elemento principal das cenas escuras
const Glow: React.FC<{ y: number; a?: number; r?: number }> = ({ y, a = 0.16, r = 620 }) => (
  <div style={{ position: "absolute", left: 540 - r, top: y - r, width: r * 2, height: r * 2, borderRadius: "50%", background: `radial-gradient(circle, rgba(245,138,60,${a}) 0%, rgba(245,138,60,0) 68%)` }} />
);
const mil = (v: number) => `${v.toFixed(1).replace(".", ",")} mil`;

// ───────── 1 · a pergunta (visual genérico, sem marca) ─────────
const Heart: React.FC<{ s: number; c: string }> = ({ s, c }) => (
  <svg width={s} height={s} viewBox="0 0 24 24" fill={c}><path d="M12 20.500s-7.500-4.600-7.500-10.200A4.300 4.300 0 0112 7.600a4.300 4.300 0 017.500 2.700c0 5.600-7.500 10.200-7.500 10.200z" /></svg>
);
const S1: React.FC<{ t: number }> = ({ t }) => {
  const a = t < C.porque, b = t >= C.porque && t < C.insta;
  const segV = 9.6 + 2.8 * k(t, C.insta, 2.6);
  const cam = 1 + 0.1 * lin(t, C.insta, T2);
  return (
    <AbsoluteFill style={{ background: b ? ORANGE : BG }}>
      {a ? (
        <AbsoluteFill style={{ alignItems: "center", justifyContent: "center" }}>
          <div style={{ fontFamily: FONT, fontWeight: 900, fontSize: 168, lineHeight: 0.98, letterSpacing: "-0.03em", color: WHITE, textAlign: "center", transform: `scale(${(1.5 - 0.5 * k(t, -LEAD, 0.3)).toFixed(4)})` }}>
            VOCÊ<br />SABE
          </div>
        </AbsoluteFill>
      ) : b ? (
        <AbsoluteFill style={{ alignItems: "center", justifyContent: "center" }}>
          <div style={{ fontFamily: FONT, fontWeight: 900, fontSize: 200, lineHeight: 0.98, letterSpacing: "-0.03em", color: INK, textAlign: "center", transform: `scale(${(0.6 + 0.4 * pop(t, C.porque, 0.26)).toFixed(4)}) rotate(${(-5 + 5 * k(t, C.porque, 0.3)).toFixed(2)}deg)` }}>
            POR<br />QUÊ?
          </div>
        </AbsoluteFill>
      ) : (
        <>
          <Glow y={980} a={0.13} />
          <Title t={t} top={236} size={96} items={[["Seu Instagram", C.insta], [<O key="o">não converte</O>, C.nao]]} />
          <div style={{ position: "absolute", inset: 0, transform: `scale(${cam.toFixed(4)})`, transformOrigin: "50% 62%" }}>
            {/* seguidores: sobem sem parar */}
            <div style={{ position: "absolute", left: 120, top: 620, width: COL, height: 330, borderRadius: 44, background: CARD, border: `3px solid ${t >= C.seg ? ORANGE : EDGE}`, opacity: Math.min(1, pop(t, C.insta + 0.1, 0.3) * 2), transform: `scale(${((0.8 + 0.2 * pop(t, C.insta + 0.1)) * (1 + 0.05 * bump(t, C.seg, 0.35))).toFixed(4)})`, overflow: "hidden" }}>
              {[0, 1, 2, 3, 4].map((i) => {
                const p = ((t * 0.55 + i * 0.21) % 1 + 1) % 1;
                return <div key={i} style={{ position: "absolute", left: 500 + i * 62 + Math.sin(t * 3 + i) * 10, top: 330 - p * 400, opacity: 0.55 * Math.sin(p * Math.PI) }}><Heart s={44 + (i % 3) * 12} c={ORANGE} /></div>;
              })}
              <Caps style={{ position: "absolute", left: 56, top: 54 }}>Seguidores</Caps>
              <div style={{ position: "absolute", left: 52, top: 118, fontFamily: FONT, fontWeight: 900, fontSize: 138, letterSpacing: "-0.03em", color: WHITE, fontVariantNumeric: "tabular-nums", whiteSpace: "nowrap" }}>{mil(segV)}</div>
            </div>
            {/* seta */}
            <svg width={90} height={110} viewBox="0 0 90 110" style={{ position: "absolute", left: 495, top: 978, opacity: lin(t, C.seg + 0.35, C.seg + 0.5), transform: `translateY(${(Math.sin(t * 7) * 6).toFixed(1)}px)` }} fill="none" stroke={DIM} strokeWidth={8} strokeLinecap="round" strokeLinejoin="round"><path d="M45 8v88M14 66l31 32 31-32" /></svg>
            {/* clientes: parado no zero */}
            <div style={{ position: "absolute", left: 120, top: 1116, width: COL, height: 330, borderRadius: 44, background: CARD, border: `3px solid ${EDGE}`, opacity: Math.min(1, pop(t, C.cli, 0.3) * 2), transform: `translateX(${shake(t, C.cli + 0.3, 0.55).toFixed(1)}px) scale(${(0.8 + 0.2 * pop(t, C.cli)).toFixed(4)})` }}>
              <Caps style={{ position: "absolute", left: 56, top: 54 }}>Clientes</Caps>
              <div style={{ position: "absolute", left: 52, top: 118, fontFamily: FONT, fontWeight: 900, fontSize: 138, color: DIM }}>0</div>
              <svg width={360} height={120} viewBox="0 0 360 120" style={{ position: "absolute", right: 56, top: 150 }} fill="none" stroke={EDGE} strokeWidth={8} strokeLinecap="round"><path d="M6 96h348" /><circle cx={6 + 348 * (((t * 0.5) % 1 + 1) % 1)} cy="96" r="9" fill={DIM} stroke="none" /></svg>
            </div>
          </div>
        </>
      )}
    </AbsoluteFill>
  );
};

// ───────── 2 · não é a quantidade ─────────
const S2: React.FC<{ t: number }> = ({ t }) => {
  const v = 12.4 + 36.3 * io(t, T2 + 0.2, C.quant);
  const cut = k(t, C.quant, 0.3);
  const cam = 0.95 + 0.08 * lin(t, T2, T3);
  return (
    <AbsoluteFill style={{ background: BG }}>
      <Title t={t} top={236} size={78} items={[["Talvez o problema", C.talvez], [<>não seja a <O>quantidade</O></>, C.talvez + 0.7, 66]]} />
      <div style={{ position: "absolute", inset: 0, transform: `scale(${cam.toFixed(4)})`, transformOrigin: "50% 55%" }}>
        <div style={{ position: "absolute", left: 0, right: 0, top: 640, display: "flex", justifyContent: "center", transform: `translateX(${shake(t, C.quant, 0.4, 10).toFixed(1)}px)` }}>
          <div style={{ position: "relative", opacity: Math.min(1, pop(t, T2 + 0.15, 0.3) * 2) }}>
            <div style={{ fontFamily: FONT, fontWeight: 900, fontSize: 176, letterSpacing: "-0.03em", color: cut > 0.5 ? "rgba(255,255,255,0.3)" : WHITE, fontVariantNumeric: "tabular-nums", whiteSpace: "nowrap" }}>{mil(v)}</div>
            <div style={{ position: "absolute", left: "-3%", top: "50%", width: `${106 * cut}%`, height: 16, borderRadius: 8, background: ORANGE, transform: "rotate(-5deg)", transformOrigin: "0 50%" }} />
          </div>
        </div>
        <Caps size={34} style={{ position: "absolute", left: 0, right: 0, top: 870, textAlign: "center", opacity: lin(t, T2 + 0.3, T2 + 0.5) * (1 - 0.5 * cut) }}>seguidores</Caps>
        {/* cada ponto é um seguidor chegando */}
        <div style={{ position: "absolute", left: 150, top: 1010, width: 780, display: "grid", gridTemplateColumns: "repeat(10, 1fr)", rowGap: 22, justifyItems: "center" }}>
          {Array.from({ length: 60 }, (_, i) => {
            const at = T2 + 0.3 + ((i * 37) % 60) * ((C.quant - T2 - 0.4) / 60);
            const e = pop(t, at, 0.25);
            return <div key={i} style={{ width: 46, height: 46, borderRadius: "50%", background: cut > 0.5 ? EDGE : i % 7 === 0 ? ORANGE : "#3A4454", opacity: e > 0 ? 1 : 0, transform: `scale(${(e * (1 - 0.25 * cut)).toFixed(3)})` }} />;
          })}
        </div>
      </div>
    </AbsoluteFill>
  );
};

// ───────── 3 · a marca e o Raio-X ─────────
const PW = 470, PH = 940;
// perfil genérico; com x = true vira o "raio-x": só contornos na cor da marca
const Phone: React.FC<{ x?: boolean }> = ({ x = false }) => {
  const box = (fill: string): React.CSSProperties => (x ? { border: `3px solid ${ORANGE}`, background: "rgba(245,138,60,0.1)" } : { background: fill });
  const bar = (w: number, fill: string, h = 14, mt = 0) => <div style={{ width: w, height: h, borderRadius: h / 2, marginTop: mt, ...box(fill) }} />;
  return (
    <div style={{ width: PW, height: PH, borderRadius: 66, border: `5px solid ${x ? ORANGE : "#39424F"}`, background: x ? "#1B1109" : "#0E131A", overflow: "hidden", position: "relative", boxSizing: "border-box" }}>
      <div style={{ position: "absolute", left: 165, top: 20, width: 130, height: 30, borderRadius: 16, ...box("#000") }} />
      <div style={{ position: "absolute", left: 34, top: 90, display: "flex", alignItems: "center", gap: 30 }}>
        <div style={{ width: 104, height: 104, borderRadius: "50%", boxSizing: "border-box", border: `5px solid ${ORANGE}`, background: x ? "transparent" : "#222A35" }} />
        {[0, 1, 2].map((i) => <div key={i} style={{ display: "flex", flexDirection: "column", alignItems: "center" }}>{bar(56, "#E7EAEE", 18)}{bar(70, "#4A5463", 10, 12)}</div>)}
      </div>
      <div style={{ position: "absolute", left: 34, top: 226 }}>{bar(190, "#E7EAEE", 16)}{bar(330, "#4A5463", 12, 16)}{bar(280, "#4A5463", 12, 12)}{bar(210, "#3D6FA8", 12, 12)}</div>
      <div style={{ position: "absolute", left: 34, top: 356, display: "flex", gap: 18 }}>
        {[0, 1, 2, 3, 4].map((i) => <div key={i} style={{ width: 64, height: 64, borderRadius: "50%", boxSizing: "border-box", ...box("#1D242E"), border: x ? `3px solid ${ORANGE}` : "3px solid #39424F" }} />)}
      </div>
      <div style={{ position: "absolute", left: 5, right: 5, top: 470, display: "grid", gridTemplateColumns: "repeat(3, 1fr)", gap: 5 }}>
        {["#2B3340", "#1A2029", "#4B3626", "#1A2029", "#3A4454", "#2B3340", "#4B3626", "#2B3340", "#1A2029"].map((c, i) => <div key={i} style={{ height: 148, boxSizing: "border-box", ...box(c) }} />)}
      </div>
    </div>
  );
};
const Tag: React.FC<{ t: number; at: number; x: number; y: number; children: React.ReactNode }> = ({ t, at, x, y, children }) => (
  <div style={{ position: "absolute", left: x, top: y, padding: "14px 26px", borderRadius: 40, background: ORANGE, fontFamily: FONT, fontWeight: 800, fontSize: 30, letterSpacing: "0.08em", color: INK, whiteSpace: "nowrap", opacity: Math.min(1, pop(t, at, 0.25) * 2), transform: `scale(${pop(t, at, 0.32).toFixed(4)})`, transformOrigin: "0 50%" }}>{children}</div>
);
const NOPE = ["Análise genérica", "PDF igual para todo mundo", "Dicas copiadas da internet"];
const S3: React.FC<{ t: number }> = ({ t }) => {
  const sub = t < C.analise - 0.1 ? 0 : t < C.receita - 0.1 ? 1 : 2;
  const ph = io(t, C.analise - 0.1, C.analise + 0.5);          // aproxima no celular
  const gone = io(t, C.receita - 0.25, C.receita + 0.05);
  const scan = 0.5 - 0.5 * Math.cos((t - C.conheca) * 2.6);    // faixa de leitura, vai e volta
  const sy = 40 + (PH - 80) * scan;
  const band = 110;
  return (
    <AbsoluteFill style={{ background: BG }}>
      <Glow y={1200} a={0.15 * (1 - gone)} />
      <div style={{ position: "absolute", left: 0, right: 0, top: 120, display: "flex", justifyContent: "center", opacity: lin(t, C.conheca, C.conheca + 0.25), transform: `scale(${(0.7 + 0.3 * pop(t, C.conheca, 0.4)).toFixed(4)})` }}>
        <Img src={staticFile("inova/logo.png")} style={{ height: 150, width: 150 * (868 / 922) }} />
      </div>
      {sub === 0 && (
        <Title t={t} top={306} size={74} out={C.analise - 0.26} items={[[<>RAIO<O>-X</O></>, C.raiox, 200], [<>DO SEU <O>INSTAGRAM</O></>, C.raiox + 0.5, 70]]} />
      )}
      {sub === 1 && (
        <Title t={t} top={326} size={96} out={C.receita - 0.26} items={[["Análise", C.analise], [<O key="o">100% personalizada</O>, C.cem, 76]]} />
      )}
      {sub === 2 && (
        <Title t={t} top={326} size={96} items={[["Não é", C.receita - 0.05], [<O key="o">receita de bolo</O>, C.receita + 0.2, 90]]} />
      )}
      {/* celular com a faixa de raio-x */}
      {gone < 1 && (
        <div style={{ position: "absolute", left: 540 - PW / 2, top: 700, width: PW, height: PH, opacity: Math.min(1, pop(t, C.raiox + 0.2, 0.3) * 2) * (1 - gone), transform: `translateY(${(-40 * ph).toFixed(1)}px) scale(${((0.75 + 0.25 * pop(t, C.raiox + 0.2, 0.45)) * (1 + 0.1 * ph) * (1 - 0.2 * gone)).toFixed(4)}) rotate(${(Math.sin(t * 1.3) * 1.2).toFixed(2)}deg)`, transformOrigin: "50% 40%" }}>
          <Phone />
          <div style={{ position: "absolute", inset: 0, clipPath: `inset(${Math.max(0, sy - band)}px 0 ${Math.max(0, PH - sy - band)}px 0 round 66px)` }}><Phone x /></div>
          <div style={{ position: "absolute", left: -46, right: -46, top: sy - 3, height: 6, borderRadius: 3, background: ORANGE, boxShadow: "0 0 26px rgba(245,138,60,0.75)" }} />
          <Tag t={t} at={C.cem + 0.1} x={PW - 110} y={236}>BIO</Tag>
          <Tag t={t} at={C.cem + 0.5} x={PW - 150} y={362}>DESTAQUES</Tag>
          <Tag t={t} at={C.cem + 0.9} x={PW - 110} y={640}>FEED</Tag>
        </div>
      )}
      {/* o que a análise não é: cada um riscado numa batida */}
      {sub === 2 && NOPE.map((w, i) => {
        const at = C.receita + 0.1 + i * 0.36;
        const st = k(t, at + 0.16, 0.2);
        return (
          <div key={i} style={{ position: "absolute", left: 0, right: 0, top: 800 + i * 210, display: "flex", justifyContent: "center", opacity: Math.min(1, pop(t, at, 0.22) * 2), transform: `scale(${(0.7 + 0.3 * pop(t, at, 0.28)).toFixed(4)}) rotate(${[-2, 1.5, -1][i]}deg)` }}>
            <div style={{ position: "relative", padding: "40px 46px", borderRadius: 40, background: CARD, border: `3px solid ${EDGE}`, fontFamily: FONT, fontWeight: 700, fontSize: 52, color: st > 0.5 ? DIM : WHITE, whiteSpace: "nowrap" }}>
              {w}
              <div style={{ position: "absolute", left: 30, top: "50%", width: `calc(${st * 100}% - ${60 * st}px)`, height: 10, marginTop: -5, borderRadius: 5, background: ORANGE }} />
            </div>
          </div>
        );
      })}
    </AbsoluteFill>
  );
};

// ───────── 4 · o que você descobre ─────────
const Gauge: React.FC<{ t: number; at: number }> = ({ t, at }) => {
  const p = 0.72 * interpolate(t, [at, at + 0.9], [0, 1], { ...cl, easing: Easing.out(Easing.back(1.2)) }) + 0.012 * Math.sin(t * 9) * lin(t, at + 0.9, at + 1.1);
  const len = Math.PI * 290;
  return (
    <div style={{ position: "relative", width: 700, height: 560 }}>
      <svg width={700} height={400} viewBox="0 0 700 400" fill="none" strokeLinecap="round">
        <path d="M60 360A290 290 0 01640 360" stroke={EDGE} strokeWidth={44} />
        <path d="M60 360A290 290 0 01640 360" stroke={ORANGE} strokeWidth={44} strokeDasharray={`${(len * Math.max(0.001, p)).toFixed(1)} 3000`} />
        <g transform={`rotate(${(-90 + 180 * p).toFixed(2)} 350 360)`}><path d="M350 360V130" stroke={WHITE} strokeWidth={12} /></g>
        <circle cx="350" cy="360" r="22" fill={WHITE} />
      </svg>
      <div style={{ position: "absolute", left: 0, right: 0, top: 404, textAlign: "center", fontFamily: FONT, fontWeight: 900, fontSize: 132, color: WHITE, fontVariantNumeric: "tabular-nums", lineHeight: 1 }}>
        {(p * 10).toFixed(1).replace(".", ",")}<span style={{ fontSize: 56, color: DIM, fontWeight: 700 }}> /10</span>
      </div>
    </div>
  );
};
const Locked: React.FC<{ t: number; at: number }> = ({ t, at }) => (
  <div style={{ position: "relative", width: 760, height: 600 }}>
    {/* o teto: as vendas batem e não passam */}
    <svg width={760} height={12} style={{ position: "absolute", left: 0, top: 300 }}><path d="M6 6h748" stroke={ORANGE} strokeWidth={8} strokeLinecap="round" strokeDasharray="26 22" strokeDashoffset={(-t * 60).toFixed(1)} /></svg>
    {[0, 1, 2, 3, 4].map((i) => {
      const h = 130 + 130 * bump(t, at + 0.25 + i * 0.22, 0.42) * 1.3 + 30 * Math.max(0, Math.sin(t * 6 + i * 1.7));
      return <div key={i} style={{ position: "absolute", left: 40 + i * 144, bottom: 0, width: 104, height: Math.min(282, h), borderRadius: 18, background: "#3A4454" }} />;
    })}
    <div style={{ position: "absolute", left: 270, top: 30, transform: `translateX(${shake(t, at + 0.2, 0.6, 12).toFixed(1)}px) scale(${pop(t, at, 0.35).toFixed(4)}) rotate(${(shake(t, at + 0.2, 0.6, 5)).toFixed(2)}deg)`, transformOrigin: "50% 80%" }}>
      <svg width={220} height={250} viewBox="0 0 220 250" fill="none"><path d="M56 112V78a54 54 0 01108 0v34" stroke={WHITE} strokeWidth={22} strokeLinecap="round" /><rect x="20" y="108" width="180" height="136" rx="30" fill={ORANGE} /><circle cx="110" cy="166" r="17" fill={INK} /><path d="M110 170v32" stroke={INK} strokeWidth={13} strokeLinecap="round" /></svg>
    </div>
  </div>
);
const FIX = ["Bio", "Destaques", "Feed"];
const Priority: React.FC<{ t: number; at: number }> = ({ t, at }) => (
  <div style={{ width: 750, display: "flex", flexDirection: "column", gap: 30 }}>
    {FIX.map((w, i) => {
      const a = at + 0.1 + i * 0.22, first = i === 0;
      const ck = pop(t, at + 0.75, 0.3);
      return (
