// ───────── montagem: cada troca de cena de um jeito ─────────
export const Inova: React.FC = () => {
  const t = useCurrentFrame() / INOVA_FPS - LEAD;
  const p2 = io(t, T2 - 0.2, T2 + 0.15);        // 1→2: a nova empurra de baixo
  const o3 = io(t, T3 - 0.32, T3 - 0.04);       // 2→3: círculo laranja, depois a cena
  const p3 = io(t, T3 - 0.06, T3 + 0.3);
  const p4 = io(t, T4 - 0.2, T4 + 0.2);         // 3→4: faixa inclinada
  const p5 = io(t, T5 - 0.2, T5 + 0.16);        // 4→5: abre do meio para os lados
  const p6 = io(t, T6 - 0.2, T6 + 0.18);        // 5→6: a nova entra pela direita
  const band = -30 + 160 * p4;
  return (
    <AbsoluteFill style={{ background: BG, overflow: "hidden" }}>
      {t < T2 + 0.2 && <AbsoluteFill style={{ transform: `translateY(${(-28 * p2).toFixed(2)}%)` }}><S1 t={t} /></AbsoluteFill>}
      {p2 > 0 && t < T3 + 0.35 && <AbsoluteFill style={{ transform: `translateY(${(100 - 100 * p2).toFixed(2)}%)` }}><S2 t={t} /></AbsoluteFill>}
      {o3 > 0 && t < T3 + 0.35 && <AbsoluteFill style={{ background: ORANGE, clipPath: `circle(${(o3 * 120).toFixed(2)}% at 50% 45%)` }} />}
      {p3 > 0 && t < T4 + 0.25 && <AbsoluteFill style={{ clipPath: `circle(${(p3 * 120).toFixed(2)}% at 50% 45%)` }}><S3 t={t} /></AbsoluteFill>}
      {p4 > 0 && p4 < 1 && <AbsoluteFill style={{ background: ORANGE, clipPath: `polygon(0 0, ${band + 12}% 0, ${band - 18}% 100%, 0 100%)` }} />}
      {p4 > 0 && t < T5 + 0.2 && <AbsoluteFill style={{ clipPath: `polygon(0 0, ${band}% 0, ${band - 30}% 100%, 0 100%)` }}><S4 t={t} /></AbsoluteFill>}
      {p5 > 0 && t < T6 + 0.22 && <AbsoluteFill style={{ clipPath: `inset(0 ${(50 - 50 * p5).toFixed(2)}% 0 ${(50 - 50 * p5).toFixed(2)}%)`, transform: `translateX(${(-100 * p6).toFixed(2)}%)` }}><S5 t={t} /></AbsoluteFill>}
      {p6 > 0 && <AbsoluteFill style={{ transform: `translateX(${(100 - 100 * p6).toFixed(2)}%)` }}><S6 t={t} /></AbsoluteFill>}
    </AbsoluteFill>
  );
};

